/// The bound on `name`, or `None` where the domain is not stated.
#[must_use]
pub fn parameter_bound(name: &str) -> Option<&'static ParameterBound> {
    PARAMETER_BOUNDS
        .iter()
        .find(|(parameter, _)| *parameter == name)
        .map(|(_, bound)| bound)
}
